package com.example.todo.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date; @Service public class JwtService { private final SecretKey key; private final long exp; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long exp){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.exp=exp;} public String generateToken(String u){Date n=new Date();return Jwts.builder().subject(u).issuedAt(n).expiration(new Date(n.getTime()+exp)).signWith(key).compact();} public String username(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();} public boolean valid(String t){try{username(t);return true;}catch(JwtException|IllegalArgumentException e){return false;}} }
